const a={meta:{title:"POP · SaaS dla twórców UEFN"},nav:{features:"Funkcje",pricing:"Cennik",faq:"FAQ",login:"Zaloguj się",join:"Dołącz do bety",home:"POP, strona główna",lang:"Język",search:"Szukaj kraju"},menu:{groups:["Organizacja","Połącz UEFN","Rozwijaj mapę"],items:[{t:"Zadania i planowanie",d:"Zadania na godzinę, kamienie milowe, śledzone opóźnienia."},{t:"Strony",d:"Dokumenty, zasady i bazy danych mapy."},{t:"Tablica",d:"Karteczki, kształty i strzałki, razem na żywo."},{t:"Zespół i role",d:"Zaproś, nadaj rolę, każdy wie, co robić."},{t:"Organizer",d:"Aktorzy poziomu uporządkowani i edytowani zbiorczo."},{t:"UEFN Link",d:"Twoje projekty UEFN zsynchronizowane z POP."},{t:"Połączone AI",d:"Claude, Cursor lub Codex realizują twoje zadania."},{t:"POP Forge",d:"Aplikacja desktopowa, która buduje w UEFN."},{t:"Analiza rynku",d:"Gatunki, które przyciągają, i te nasycone."},{t:"Trendy wideo",d:"Co jest hitem na TikToku i YouTube Shorts."},{t:"Playtesty i premiera",d:"Daj mapę do testów i przygotuj premierę."},{t:"Wypłaty",d:"Podział zarobków i zestawienie dla każdego."}],bottom:["Discord i GitHub połączone","Na Macu i PC"],all:"Wszystkie funkcje"},hero:{announce:"Zamknięta beta otwarta dla twórców UEFN",h1a:"Twórz w UEFN.",h1b:"Sam lub w zespole, bez chaosu.",subA:"POP to SaaS, który pomaga twórcom UEFN od pomysłu do premiery: ",subB:"zadania na godzinę",subC:", tablica, połączone AI, analiza rynku i podział zarobków.",cta:"Dołącz do listy oczekujących",see:"Zobacz funkcje",micro1:"Zamknięta beta",micro2:"Dostęp z listy oczekujących",micro3:"Połączony z UEFN"},marquee:{label:"Działa z twoimi narzędziami",epic:"API Fortnite od Epic"},pain:{eyebrow:"Problem",h2a:"Discord, Google Docs, pliki wszędzie…",h2b:"a mapa stoi w miejscu.",without:"Bez POP",with:"Z POP",bad:["„Kto ruszał spawner?”","Pomysły giną na Discordzie","Lista zadań w Google Doc","Arkusz zarobków, wersja 7","„To kiedy w końcu wydajemy?”","Budujemy, nie wiedząc, czy gatunek działa"],good:["Każda akcja jest zapisana i odwracalna","Pomysły z tablicy stają się zadaniami","Zadania na godzinę, z zależnościami","Jasne zestawienie dla każdego","Kamienie milowe i opóźnienia śledzone automatycznie","Werdykt dla każdego gatunku, na prawdziwych danych"]},feat:{eyebrow:"Funkcje",h2:"Wszystko do tworzenia w UEFN, od pomysłu do premiery.",p:"To, co tu widzisz, to prawdziwe ekrany POP, w uproszczeniu.",items:[{tag:"Zadania i planowanie",h:"Zadania na godzinę. Plan, który się trzyma.",p:"Generator dzieli mapę na zadania na godzinę z zależnościami. Plan śledzi kamienie milowe i zgłasza opóźnienia, a wbudowany asystent podsumowuje dzień.",pts:["Kanban i zależności","Kamienie milowe i opóźnienia","Podsumowanie dnia"]},{tag:"Organizer",h:"Wszystkie urządzenia. Uporządkowane w trzy sekundy.",p:"Szukaj po tagu, typie lub folderze, zaznacz dwadzieścia i zmień nazwę, przenieś lub zduplikuj za jednym razem. Ctrl+Z cofa. Gdy UEFN jest zamknięty, zmiany czekają.",pts:["Wyszukiwanie tag:, type:, folder:","Zmiany zbiorcze","Wszystko można cofnąć"]},{tag:"Tablica",h:"Rysujcie mapę razem.",p:"Karteczki, kształty, strzałki, kolory, pogrubienie, podkreślenie: wszystko, by rozpisać pomysły. Głosujcie, a najlepsze karteczki zamieńcie w zadania.",pts:["Pełne formatowanie","Współpraca na żywo","Karteczki → zadania"]},{tag:"Analiza",h:"Wiedz, co budować, zanim zaczniesz.",p:"Które gatunki przyciągają graczy, gdzie jest miejsce, które mapy startują od premiery i co jest hitem w wideo. Dane z oficjalnego API Epic.",pts:["Werdykt dla gatunku","Mapy, które działają","Trendy TikTok i Shorts"]},{tag:"Wypłaty",h:"Każdy wie, ile zarabia.",p:"Zasady podziału procentowe, stałe lub za zadanie, import zarobków, zestawienie dla każdej osoby. Koniec z arkuszem zgubionym na Discordzie.",pts:["Procent, stała kwota, za zadanie","Import CSV","Zestawienie dla każdego"]}],aiB:"Masz już AI?",aiText:"Połącz Claude, Cursor, Codex lub inne AI zgodne z MCP: bierze zadanie, pisze Verse, kompiluje i zamyka zadanie z notatką. Każda akcja jest zapisana i odwracalna. Zgodne: Claude Code, Claude Desktop, Cursor, Codex, Windsurf, VS Code (GitHub Copilot), Gemini CLI."},stats:[["1 h","na zadanie, by codziennie iść do przodu"],["0","wymaganych zewnętrznych usług AI"],["7 dni","statystyk na mapę, z API Epic"],["100%","akcji w UEFN do cofnięcia"]],pricing:{eyebrow:"Cennik",h2:"Wybierz plan.",p:"POP jest w zamkniętej becie: dostęp przez listę oczekujących. Po otwarciu każde konto zaczyna od 7 dni darmowego okresu próbnego Pro, bez karty.",perMonth:"/ mies.",compare:"Porównaj plany",unlimited:"Bez limitu",soon:"Wkrótce",plans:[{name:"Starter",tag:"Do tworzenia",desc:"Cała przestrzeń robocza do tworzenia map, solo lub w zespole.",cta:"Dołącz do listy"},{name:"Pro",tag:"Najpełniejszy",desc:"Wszystko ze Starter oraz analiza: pomysły na mapy, rynek, śledzenie Discover.",cta:"Dołącz do listy"}],rows:["Organizacja","Zadania na godzinę, Kanban, zależności","Wbudowany asystent (podsumowanie dnia, opóźnienia)","Strony, tablica, planowanie i kamienie milowe","Mapy","Członkowie","UEFN","UEFN Link: zsynchronizowane projekty","Organizer aktorów i zmiany zbiorcze","Połączone AI (Claude, Cursor, Codex…)","POP Forge: wspomagane budowanie w UEFN","Rozwój","Pomysły na mapy, analiza rynku, śledzenie Discover","Trendy wideo TikTok i YouTube Shorts","Wymiana playtestów i dzień premiery","Podział zarobków i zestawienia","Discord, GitHub, Lore"],perDay:["Mniej niż 0,50 € dziennie","Mniej niż 1 € dziennie"],hints:["","Mapa podzielona na godzinne zadania, z tym, co co blokuje","Każdego ranka: co jest opóźnione i od czego zacząć","Dokumentacja mapy, pomysły na żywo i kalendarz","Tyle map, ile chcesz","Zaproś cały zespół bez dopłat","","Twoje AI widzą prawdziwy projekt UEFN: aktorów i Verse","","Podłącz swoje AI przez MCP; każdą akcję można cofnąć","Budowanie w UEFN na podstawie prośby","","Gatunki, które przyciągają graczy, i gdzie jest jeszcze miejsce","Co teraz rośnie na TikToku i YouTube Shorts","Znajdź testerów i przygotuj dzień premiery","Kto ile dostaje, z rozliczeniem dla każdego","Powiadomienia i linki do twoich narzędzi"]},faq:{eyebrow:"FAQ",h2:"Pytania, które słyszymy.",items:[["Czy potrzebuję PC z Windows?","Do połączenia z UEFN tak: UEFN działa tylko na Windows, a UEFN Link uruchamia się na tym PC. Reszta POP działa w każdej przeglądarce, także na Macu."],["Czy POP publikuje moją mapę?","Nie. POP przygotowuje wszystko (kontrola przed publikacją, playtesty, plan dnia premiery), ale publikacja zawsze odbywa się w portalu twórców Epic."],["Czy POP działa, jeśli tworzę sam?","Tak. POP służy zarówno twórcom solo, jak i zespołom, już od planu Starter: możesz później zaprosić członków bez żadnych zmian."],["Jakie AI mogę połączyć?","Te, które obsługują serwery MCP: Claude Code, Claude Desktop, Cursor, Codex, Windsurf, VS Code (GitHub Copilot), Gemini CLI. Claude Desktop wymaga, by POP był dostępny online przez HTTPS. Subskrypcja twojego AI nie jest wliczona w POP. Czatowe AI w przeglądarce (ChatGPT, Gemini, Copilot w sieci) na razie nie są obsługiwane. Po połączeniu w „Połączone AI” twoje AI czyta i edytuje zadania oraz aktorów UEFN, pisze Verse, a każda akcja jest zapisana i odwracalna."],["Skąd pochodzą dane w analizie?","Z oficjalnego API Fortnite od Epic: gracze, szczyt jednoczesnych graczy, czas gry i retencja każdej publicznej mapy, z 7 dni."],["Jak uzyskać dostęp?","POP jest w zamkniętej becie. Dołącz do listy oczekujących: sprawdzamy zgłoszenia pojedynczo, a potem wysyłamy ci login i tymczasowe hasło, które zmienisz przy pierwszym logowaniu."],["Ile to kosztuje?","Ceny są podane wyżej. Obowiązują od otwarcia POP; uczestnicy bety zostaną powiadomieni przed każdą płatnością."]]},final:{h2a:"Twoja następna mapa",h2b:"zaczyna się tutaj.",p:"Dołącz do listy oczekujących: wyślemy ci dostęp, gdy tylko zwolni się miejsce."},foot:{legalTitle:"Informacje prawne",made:"Stworzone przez twórców Fortnite, dla twórców Fortnite.",legal:"Fortnite i UEFN są znakami towarowymi Epic Games. POP nie jest powiązany z Epic Games ani przez nie wspierany.",product:"Produkt",help:"Pomoc",account:"Konto"},mock:{overview:"Przegląd",nav:["Przegląd","Strony","Tablica","Zadania","Organizer","Rynek"],hello:"Cześć Léa, proponuję zacząć od #42.",late:"2 zadania opóźnione (najstarsze miało termin 12 lis.).",mile:"Kamień milowy „Beta” za 5 dni: zostało 9 zadań, przewidywane opóźnienie 1 dzień.",take:"Weź",start:"Zacznij",unlocks:"odblokowuje 3 inne zadania",today:"termin dziś",waits:"czeka na #42",todo:"Do zrobienia",doing:"W toku",done:"Zrobione",tasks:["System punktów","Scenografia strefy 2","Ekran końcowy","Wewnętrzny playtest","Spawn graczy","Burza"],sent:"wysłano do UEFN",err:"Linia 12: nie można dodać int i float.",fix:"Popraw: Points += 1",red:"Drużyna czerwona",selected:"2 zaznaczone",rename:"Zmień nazwę",move:"Przenieś",dup:"Duplikuj",s1:"Tryb drużynowy 4v4",s2a:"Boss końcowy",s2b:"na środku",s3:"Ekonomia: 1 moneta / eliminacja",verdicts:["Dobra okazja","Popularny, ale zatłoczony","Nasycony","Nisza"],typical:"graczy / typowa mapa",earnings:"Zarobki z października",roles:["Kod · 40%","Mapa · 35%","Muzyka · stała","Reszta"],noTransfer:"POP liczy, nigdy nie przelewa pieniędzy."},wl:{eyebrow:"Zamknięta beta",title:"Dołącz do listy oczekujących",intro:"Otwieramy POP stopniowo, by zadbać o każdego twórcę. Powiedz nam, kim jesteś, a wyślemy ci dostęp jak najszybciej.",pageIntro:"W czasie bety konta POP zakłada zespół. Powiedz nam, kim jesteś: po zatwierdzeniu dostępu otrzymasz login i tymczasowe hasło.",invalid:"Ten link dostępu jest nieprawidłowy, już użyty lub wygasł. Złóż prośbę ponownie albo napisz do zespołu POP.",name:"Imię lub pseudonim",email:"E-mail",studio:"Studio",optional:"(opcjonalnie)",studioPh:"Nazwa studia",team:"Wielkość zespołu",teams:["Sam","2–3","4–10","Ponad 10"],exp:"Doświadczenie",exps:["Nowy w UEFN","Kilka opublikowanych map","Doświadczony twórca","Profesjonalne studio"],links:"Twoje mapy lub social media",linksPh:"Kody wysp, TikTok, YouTube…",msg:"Co chcesz robić z POP",msgPh:"Np. jesteśmy w 4 osoby przy mapie tycoon i gubimy się między Discordem a Google Docs.",send:"Poproś o dostęp",sending:"Wysyłanie…",nospam:"Bez spamu: piszemy tylko po to, by dać ci dostęp.",privacy:"Polityka prywatności",okTitle:"Zapisane, dziękujemy!",okText:"Gdy dostęp będzie gotowy, otrzymasz e-mail na podany adres z linkiem do aktywacji konta. Sprawdź też folder spam.",alreadyTitle:"Jesteś już na liście.",approvedTitle:"Twój dostęp jest już zatwierdzony.",approvedText:"Twoje konto jest gotowe: otrzymałeś e-mail z linkiem do jego aktywacji i wyboru hasła. Sprawdź też folder spam.",close:"Zamknij"}};export{a as default};
